SELECT * FROM lqc_records
WHERE TRUNC(check_date) = TRUNC(#{checkDate, jdbcType=DATE})
AND shift = #{shift, jdbcType=VARCHAR}
AND lot_name = #{lotName, jdbcType=VARCHAR}
