UPDATE lqc_records
record_status = #{newStatus, jdbcType=VARCHAR}, last_updated_by = #{confirmer, jdbcType=VARCHAR}, last_update_date = #{confirmDate, jdbcType=DATE},
shift_confirmed_by = #{confirmer, jdbcType=VARCHAR}, shift_confirmation_date = #{confirmDate, jdbcType=DATE},
